/* QueryId : insertCmnTmpRegFee */
INSERT INTO CMN_TMP_REG_FEE(
SCH_YEAR
, SMT_RCD
, STUD_NO
, REG_CLS_RCD
, IFR_DT
, PAY_CLOSE_DT

	, DIV_PAY_REQ_DT


	, DIV_PAY_DESC


	, DIV_PAY_TYPE_CD


	, DIV_PAY_STAT_RCD


	, DIV_PAY_NO


	, BKG_PNT


	, BKG_TIME


	, REG_STUD_DIV_RCD


	, REMARK


	, REF_KEY

, CRT_DTHR
, CRT_USER_ID
, CRT_PGM_ID
, CRT_IP_MAC
, UPD_DTHR
, UPD_USER_ID
, UPD_PGM_ID
, UPD_IP_MAC
)VALUES(
#{SCH_YEAR}
, #{SMT_RCD}
, #{STUD_NO}
, #{REG_CLS_RCD}
, TO_DATE(#{IFR_DT},'YYYYMMDD')
, TO_DATE(#{PAY_CLOSE_DT},'YYYYMMDD')

	, TO_DATE(#{DIV_PAY_REQ_DT},'YYYYMMDD')


	, #{DIV_PAY_DESC}


	, #{DIV_PAY_TYPE_CD}


	, #{DIV_PAY_STAT_RCD}


	, #{DIV_PAY_NO}


	, #{BKG_PNT}


	, #{BKG_TIME}


	, #{REG_STUD_DIV_RCD}


	, #{REMARK}


	, #{REF_KEY}

, SYSDATE
, #{CRT_USER_ID}
, #{CRT_PGM_ID}
, #{CRT_IP_MAC}
, SYSDATE
, #{UPD_USER_ID}
, #{UPD_PGM_ID}
, #{UPD_IP_MAC}
)

