/* QueryId : updateCmnTmpRegFee */
UPDATE CMN_TMP_REG_FEE SET
UPD_DTHR = SYSDATE
, UPD_USER_ID = #{UPD_USER_ID}
, UPD_PGM_ID = #{UPD_PGM_ID}
, UPD_IP_MAC = #{UPD_IP_MAC}

	, IFR_DT = TO_DATE(#{IFR_DT},'YYYYMMDD')


	, PAY_CLOSE_DT = TO_DATE(#{PAY_CLOSE_DT},'YYYYMMDD')


	
		, DIV_PAY_REQ_DT = TO_DATE(null,'YYYYMMDD')
	
	
		, DIV_PAY_REQ_DT = TO_DATE(#{DIV_PAY_REQ_DT},'YYYYMMDD')
	


	, DIV_PAY_DESC = #{DIV_PAY_DESC}


	, DIV_PAY_TYPE_CD = #{DIV_PAY_TYPE_CD}


	, DIV_PAY_STAT_RCD = #{DIV_PAY_STAT_RCD}


	, DIV_PAY_NO = #{DIV_PAY_NO}


	, BKG_PNT = #{BKG_PNT}


	, BKG_TIME = #{BKG_TIME}


	, REG_STUD_DIV_RCD = #{REG_STUD_DIV_RCD}


	, REMARK = #{REMARK}


	, REF_KEY = #{REF_KEY}

WHERE SCH_YEAR = #{SCH_YEAR__origin}
AND SMT_RCD = #{SMT_RCD__origin}
AND STUD_NO = #{STUD_NO__origin}
AND REG_CLS_RCD = #{REG_CLS_RCD__origin}

