		SELECT *
		FROM CO_SYS_DOWNLOAD_LOG_POC
		WHERE 1=1
		
			AND DOC_TYPE = #{docType}
		
		
			AND INSTR(DOC_NO, UPPER(#{docNum})) > 0
		
		
			AND INSTR(DOWN_LOADER_NAME , UPPER(#{downloader})) > 0
		
		
			AND TO_CHAR(DOWN_LOAD_DATE, 'YYYYMMDD') >=	#{fromDate}
		
		
			AND TO_CHAR(DOWN_LOAD_DATE, 'YYYYMMDD') <=	#{toDate}
		
		
			AND ROWNUM <=	#{count}
